module TopModule (
    input  clk,
    input  x,
    output z
);

    // State elements: three D flip-flops
    reg q1, q2, q3;

    // Internal wires for complemented flip-flop outputs
    wire q1_bar, q2_bar, q3_bar;

    // Assign complemented outputs
    assign q1_bar = ~q1;
    assign q2_bar = ~q2;
    assign q3_bar = ~q3;

    // Flip-Flop D-inputs derived from the specification
    // D1 = x XOR q1
    // D2 = x AND (NOT q2)
    // D3 = x OR  (NOT q3)

    always @(posedge clk) begin
        // Initial reset state: all flip-flops are zero
        // The specification states: "Assume that the D flip-flops are initially reset to zero before the machine begins."
        // We model this by initializing the registers to zero.
        // On each positive edge, the new state is computed as per the logic.
        q1 <= (q1 === 1'b0) ? (x ^ q1) : (x ^ q1); // XOR implementation
        q2 <= (q2 === 1'b0) ? (x & q2_bar) : (x & q2_bar); // AND with complemented q2
        q3 <= (q3 === 1'b0) ? (x | q3_bar) : (x | q3_bar); // OR with complemented q3
    end

    // Output logic: three-input NOR gate
    // z = NOR(q1, q2, q3) = NOT (q1 OR q2 OR q3)
    assign z = ~(q1 | q2 | q3);

    // Synthesis-friendly initialization: reset block to ensure zero state at start
    // This block ensures the flip-flops are zero at power-up/reset.
    // In Icarus Verilog simulation, this models the "initially reset to zero" behavior.
    initial begin
        q1 = 1'b0;
        q2 = 1'b0;
        q3 = 1'b0;
    end

endmodule

