module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic x,
    output logic z
);

    // State register: 3 bits, y[2:0]
    logic [2:0] y, y_next;

    // ==================================================
    // 1. Next-state logic (combinational)
    // ==================================================
    always_comb begin
        // Default: hold current state
        y_next = y;

        case (y)
            3'b000: y_next = 3'b000;           // 000 -> 000 (x don't care)
            3'b001: y_next = (x) ? 3'b100 : 3'b001; // 001 -> 100 if x=1, else 001
            3'b010: y_next = (~x) ? 3'b010 : 3'b001; // 010 -> 001 if x=1, else 010
            3'b011: y_next = (~x) ? 3'b001 : 3'b010; // 011 -> 001 if x=0, else 010
            3'b100: y_next = (~x) ? 3'b011 : 3'b100; // 100 -> 011 if x=0, else 100
            default:  y_next = 3'b000;         // Should not happen
        endcase
    end

    // ==================================================
    // 2. State register (sequential, positive edge-triggered)
    // ==================================================
    always_ff @(posedge clk) begin
        if (reset) begin
            y <= 3'b000;   // Synchronous active-high reset
        end else begin
            y <= y_next;
        end
    end

    // ==================================================
    // 3. Output logic (combinational)
    // ==================================================
    always_comb begin
        case (y)
            3'b011, 3'b100: z = 1'b1;
            default:        z = 1'b0;
        endcase
    end

endmodule

