module TopModule(
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,  // One-hot encoded: {S, S1, S11, S110, B0, B1, B2, B3, Count, Wait}

    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

// Internal wires to decode the one-hot state vector
wire w_S, w_S1, w_S11, w_S110, w_B0, w_B1, w_B2, w_B3, w_Count, w_Wait;

// Decode the one-hot state bits
assign w_S    = state[0];
assign w_S1   = state[1];
assign w_S11  = state[2];
assign w_S110 = state[3];
assign w_B0   = state[4];
assign w_B1   = state[5];
assign w_B2   = state[6];
assign w_B3   = state[7];
assign w_Count= state[8];
assign w_Wait = state[9];

// -------------------------------------------------------
// Next-State Logic (Combinational)
// -------------------------------------------------------

// S_next: transitions to S from S (d=0), S1 (d=0), S110 (any), Wait (ack=1)
assign S_next = (w_S & ~d) |
                (w_S1 & ~d) |
                w_S110 |
                (w_Wait & ack);

// S1_next: transitions to S1 from S (d=1)
assign S1_next = (w_S & d);

// B3_next: transitions to B3 from B2 (always)
assign B3_next = w_B2;

// Count_next: transitions to Count from B3 (always)
assign Count_next = w_B3;

// Wait_next: transitions to Wait from Count (done_counting=1)
assign Wait_next = (w_Count & done_counting);

// -------------------------------------------------------
// Output Logic (Moore Machine - functions of current state)
// -------------------------------------------------------

// shift_ena: asserted in states B0, B1, B2, B3
assign shift_ena = (w_B0 | w_B1 | w_B2 | w_B3);

// counting: asserted in state Count
assign counting  = w_Count;

// done: asserted in state Wait
assign done      = w_Wait;

endmodule

