Prob149_ece241_2013_q4.code:
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // State encoding
    // 2-bit state register to track previous water level category
    typedef enum logic [1:0] {
        S_HIGH       = 2'b00,  // Level above s[2]
        S_MID_HIGH   = 2'b01,  // Level between s[2] and s[1]
        S_MID_LOW    = 2'b10,  // Level between s[1] and s[0]
        S_LOW        = 2'b11   // Level below s[0]
    } state_t;

    state_t state_reg, state_next;

    // -------------------------------------------------------
    // State Register (Flip-flops)
    // -------------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= S_LOW;
        else
            state_reg <= state_next;
    end

    // -------------------------------------------------------
    // Next-State Logic
    // -------------------------------------------------------
    always_comb begin
        // Default: stay in current state
        state_next = state_reg;

        case (state_reg)
            S_HIGH: begin
                if (s == 3'b111)
                    state_next = S_HIGH;
                else if (s == 3'b110)
                    state_next = S_MID_HIGH;
                else if (s == 3'b100)
                    state_next = S_MID_LOW;
                else if (s == 3'b000)
                    state_next = S_LOW;
            end

            S_MID_HIGH: begin
                if (s == 3'b111)
                    state_next = S_HIGH;
                else if (s == 3'b110)
                    state_next = S_MID_HIGH;
                else if (s == 3'b100)
                    state_next = S_MID_LOW;
                else if (s == 3'b000)
                    state_next = S_LOW;
            end

            S_MID_LOW: begin
                if (s == 3'b111)
                    state_next = S_HIGH;
                else if (s == 3'b110)
                    state_next = S_MID_HIGH;
                else if (s == 3'b100)
                    state_next = S_MID_LOW;
                else if (s == 3'b000)
                    state_next = S_LOW;
            end

            S_LOW: begin
                if (s == 3'b111)
                    state_next = S_HIGH;
                else if (s == 3'b110)
                    state_next = S_MID_HIGH;
                else if (s == 3'b100)
                    state_next = S_MID_LOW;
                else if (s == 3'b000)
                    state_next = S_LOW;
            end
        endcase
    end

    // -------------------------------------------------------
    // Output Logic (Combinational)
    // -------------------------------------------------------

    // dfr: Supplemental Flow valve
    // Asserted if current state is S_LOW OR if a rising edge is detected
    // (transition from a lower state to a higher state).
    // rising_edge = (state_reg != S_HIGH) and (current_s > state_s)
    // We decode current_s compared to state encoding:
    //   S_HIGH   -> s == 3'b111
    //   S_MID_HIGH -> s == 3'b110
    //   S_MID_LOW  -> s == 3'b100
    //   S_LOW    -> s == 3'b000
    assign dfr = (state_reg == S_LOW) |
                 ((state_reg != S_HIGH) &&
                  ((state_reg == S_HIGH  && s == 3'b111) ||
                   (state_reg == S_MID_HIGH && s == 3'b110) ||
                   (state_reg == S_MID_LOW  && s == 3'b100) ||
                   (state_reg == S_LOW    && s == 3'b000)));

    // fr2: Highest Nominal Flow valve
    // Asserted only when water level is S_LOW
    assign fr2 = (state_reg == S_LOW);

    // fr1: Middle Nominal Flow valve
    // Asserted when level is S_MID_LOW or S_LOW
    assign fr1 = (state_reg == S_MID_LOW) | (state_reg == S_LOW);

    // fr0: Lowest Nominal Flow valve
    // Asserted in all non-S_HIGH states
    assign fr0 = (state_reg != S_HIGH);

endmodule

