Prob155_lemmings4.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding:
    // 2'b00: Walking on ground
    // 2'b01: Falling
    // 2'b10: Digging
    // 2'b11: Splattered

    reg [1:0] state;
    reg [4:0] fall_counter; // counts cycles falling (0 to 20+)
    reg walking_dir;        // 1'b0 = left, 1'b1 = right (complementary to outputs)

    // Output assignments (Moore machine: outputs depend only on state)
    assign walk_left  = (state == 2'b00) && (!walking_dir);
    assign walk_right = (state == 2'b00) &&  walking_dir;
    assign aaah       = (state == 2'b01);
    assign digging    = (state == 2'b10);

    // State register update on positive edge of clk
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            // Asynchronous reset: walk left, no fall, not digging
            state       <= 2'b00;
            fall_counter<= 5'd0;
            walking_dir <= 1'b0; // walk_left = 1, walk_right = 0
        end else begin
            case (state)
                2'b00: begin // Walking on ground
                    if (!ground) begin
                        // Fall has highest precedence
                        state       <= 2'b01;
                        fall_counter<= 5'd0;
                        // walking_dir unchanged (resume same direction when ground reappears)
                    end else if (ground && dig) begin
                        // Dig: only if on ground
                        state       <= 2'b10;
                        fall_counter<= 5'd0;
                    end else if (bump_left || bump_right) begin
                        // Switch direction
                        walking_dir <= ~walking_dir;
                        // state stays 2'b00
                    end else begin
                        // Stay walking
                        state       <= 2'b00;
                    end
                end

                2'b01: begin // Falling
                    fall_counter <= fall_counter + 5'd1;

                    if (ground) begin
                        if (fall_counter > 5'd20) begin
                            // Splat: hit ground after >20 cycles
                            state       <= 2'b11;
                        end else begin
                            // Resume walking in same direction, reset counter
                            state       <= 2'b00;
                            fall_counter<= 5'd0;
                            // walking_dir unchanged
                        end
                    end else begin
                        // Still falling, stay in falling state
                        state       <= 2'b01;
                    end
                end

                2'b10: begin // Digging
                    if (!ground) begin
                        // Reached other side, start falling
                        state       <= 2'b01;
                        fall_counter<= 5'd0;
                    end else begin
                        // Stay digging; bump and dig ignored
                        state       <= 2'b10;
                    end
                end

                2'b11: begin // Splattered (absorbing)
                    // Remain splattered forever unless reset
                    state       <= 2'b11;
                end
            endcase
        end
    end

endmodule

