    reg [15:0] count;

    // Synchronous active-high reset
    always @(posedge clk) begin
        if (reset) begin
            count <= 16'd0;
        end else begin
            // BCD increment logic
            // Ones digit (q[3:0])
            if (count[3:0] == 4'd9)
                count[3:0] <= 4'd0;
            else
                count[3:0] <= count[3:0] + 1'b1;

            // Tens digit (q[7:4]) - propagate carry from ones
            if (count[3:0] == 4'd9)
                if (count[7:4] == 4'd9)
                    count[7:4] <= 4'd0;
                else
                    count[7:4] <= count[7:4] + 1'b1;

            // Hundreds digit (q[11:8]) - propagate carry from tens
            if (count[3:0] == 4'd9 && count[7:4] == 4'd9)
                if (count[11:8] == 4'd9)
                    count[11:8] <= 4'd0;
                else
                    count[11:8] <= count[11:8] + 1'b1;

            // Thousands digit (q[15:12]) - propagate carry from hundreds
            if (count[3:0] == 4'd9 && count[7:4] == 4'd9 && count[11:8] == 4'd9)
                if (count[15:12] == 4'd9)
                    count[15:12] <= 4'd0;
                else
                    count[15:12] <= count[15:12] + 1'b1;
        end
    end

    // Assign q output directly from register
    assign q = count;

    // Enable logic assignments
    // ena[0]: Tens enable - asserted when Ones digit is 9
    // ena[1]: Hundreds enable - asserted when Tens digit is 9
    // ena[2]: Thousands enable - asserted when Hundreds digit is 9
    assign ena[0] = (count[3:0] == 4'd9);
    assign ena[1] = (count[7:4] == 4'd9);
    assign ena[2] = (count[11:8] == 4'd9);

endmodule

