module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

// State encoding
// A: Initial/reset state
// B: f pulse state
// C: Monitoring x for sequence 1,0,1
// D: g active, waiting for y
// E: g permanently 0
typedef enum logic [2:0] {
    STATE_A = 3'b000,
    STATE_B = 3'b001,
    STATE_C = 3'b010,
    STATE_D = 3'b011,
    STATE_E = 3'b100
} state_t;

// State registers
state_t   state, next_state;
logic [1:0] x_shift;   // Stores last two x values
logic [1:0] y_count;   // Counts cycles since g became 1

// Output assignments
assign f = (state == STATE_B) ? 1'b1 : 1'b0;
assign g = (state == STATE_D) ? 1'b1 : 1'b0;

// ==================================================
// 1. State Register (Positive Edge-Triggered)
// ==================================================
always_ff @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        state       <= STATE_A;
        x_shift     <= 2'b00;
        y_count     <= 2'b00;
    end else begin
        state       <= next_state;
        x_shift     <= next_x_shift;
        y_count     <= next_y_count;
    end
end

// ==================================================
// 2. Next-State Logic (Combinational)
// ==================================================
always_comb begin
    // Default assignments (stay in current state)
    next_state    = state;
    next_x_shift  = x_shift;
    next_y_count  = y_count;

    case (state)
        // ------------------------------------------
        // State A: Initial state, wait for resetn
        // ------------------------------------------
        STATE_A: begin
            if (resetn) begin
                // resetn is de-asserted (high); move to B
                next_state = STATE_B;
            end else begin
                // resetn asserted (low); stay in A
                next_state = STATE_A;
            end
        end

        // ------------------------------------------
        // State B: f pulse state
        // ------------------------------------------
        STATE_B: begin
            // f was 1 for one cycle; now move to C
            next_state = STATE_C;
        end

        // ------------------------------------------
        // State C: Monitor x for sequence 1,0,1
        // ------------------------------------------
        STATE_C: begin
            // Shift the current x value into the register
            next_x_shift = {x, x_shift[1:0]};

            // Check if the sequence 1,0,1 is detected.
            // Note: x_shift[1] is the second-last x, x_shift[0] is the last x, and x is the current x.
            if (x_shift[1] && !x_shift[0] && x) begin
                next_state = STATE_D;
            end else begin
                next_state = STATE_C;
