        // ------------------------------------------
        STATE_D: begin
            if (y) begin
                next_y_count = 2'b00;
                next_state   = STATE_D;
            end else begin
                next_y_count = y_count + 1'b1;
                if (y_count == 2'b10) begin
                    next_state = STATE_E;
                end else begin
                    next_state = STATE_D;
                end
            end
        end

        // ------------------------------------------
        // State E: g permanently 0
        // ------------------------------------------
        STATE_E: begin
            next_state = STATE_E;
        end

        default: begin
            next_state = STATE_A;
        end
    endcase
end

