module TopModule (
    input clk,
    input reset,
    input [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    reg [1:0] state;
    reg [2:0] byte_reg;
    reg [23:0] out_reg;

    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            byte_reg <= 0;
            out_reg <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3]) begin
                        state <= 1;
                    end else begin
                        state <= 0;
                    end
                end
                1: begin
                    out_reg[23:16] <= in;
                    byte_reg <= 2;
                    state <= 2;
                end
                2: begin
                    out_reg[15:8] <= in;
                    byte_reg <= 3;
                    state <= 3;
                end
                3: begin
                    out_reg[7:0] <= in;
                    done <= 1;
                    state <= 0;
                    byte_reg <= 0;
                end
                default: state <= 0;
            endcase
        end
    end

    // out_bytes is driven directly from the registered out_reg
    assign out_bytes = out_reg;

