module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

// State encoding
typedef enum logic [1:0] {
    A = 2'b00,
    B = 2'b01,
    C = 2'b10,
    D = 2'b11
} state_t;

state_t current_state, next_state;

// State register (positive edge-triggered, synchronous active high reset)
always_ff @(posedge clk) begin
    if (reset)
        current_state <= A;
    else
        current_state <= next_state;
end

// Next state logic (combinational)
always_comb begin
    case (current_state)
        A: next_state = in ? B : A;
        B: next_state = in ? B : C;
        C: next_state = in ? D : A;
        D: next_state = in ? C : B;
        default: next_state = A;
    endcase
end

// Output logic (Moore machine: output depends only on current state)
always_comb begin
    case (current_state)
        D: out = 1'b1;
        default: out = 1'b0;
    endcase
end

endmodule
